-- V30 required. Controlled offline repair ONLY: stop/drain all writers/cleanup first, including old workers.
-- Same session: CREATE TEMPORARY TABLE media_attachment_verified_mapping (
--   attachment_id BIGINT UNSIGNED PRIMARY KEY, object_key VARCHAR(512) NOT NULL,
--   uploader_id BIGINT UNSIGNED NOT NULL, cos_exists TINYINT NOT NULL,
--   evidence_ref VARCHAR(200) NOT NULL
-- ) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
-- Load <=100 reviewed rows: exact URL/key mapping, authenticated provenance, COS existence and audit evidence.
-- No mappings are generated by this script. Missing/ambiguous/deleted objects stay unresolved.
-- This script ends in ROLLBACK. Inspect its output and row counts; an approved execution may explicitly COMMIT instead.
START TRANSACTION;

SELECT r.id, r.status, r.bound_target_id, r.bound_attachment_id, r.cleanup_started_at
FROM media_upload_record r JOIN media_attachment_verified_mapping m ON BINARY r.object_key = BINARY m.object_key
ORDER BY r.id FOR UPDATE;

-- Report invalid rows before any repair; any row here requires stopping and correcting the reviewed batch.
SELECT m.*, a.registered_by, r.id AS upload_record_id, r.status, r.bound_target_id, r.bound_attachment_id
FROM media_attachment_verified_mapping m
LEFT JOIN media_attachment a ON a.id = m.attachment_id
LEFT JOIN media_upload_record r ON r.object_key = m.object_key AND BINARY r.object_key = BINARY m.object_key
WHERE a.id IS NULL OR a.registered <> 1 OR a.target_type IS NOT NULL OR a.target_id IS NOT NULL
   OR NOT (a.registered_by <=> m.uploader_id) OR r.id IS NULL OR r.user_id <> m.uploader_id
   OR r.target_type NOT IN (2,3) OR r.status NOT IN (0,1,2) OR r.bound_target_id IS NOT NULL
   OR (r.status = 1 AND r.bound_attachment_id IS NULL)
   OR (a.object_key IS NOT NULL AND BINARY a.object_key <> BINARY m.object_key)
   OR m.cos_exists <> 1 OR TRIM(m.evidence_ref) = '';

-- All-or-nothing eligibility is established by a materialized temporary batch, not partial join updates.
CREATE TEMPORARY TABLE media_attachment_eligible_mapping AS
SELECT m.attachment_id, m.object_key, r.id AS upload_record_id
FROM media_attachment_verified_mapping m
JOIN media_attachment a ON a.id = m.attachment_id
JOIN media_upload_record r ON r.object_key = m.object_key AND BINARY r.object_key = BINARY m.object_key
WHERE a.registered = 1 AND a.target_type IS NULL AND a.target_id IS NULL
  AND a.registered_by = m.uploader_id AND r.user_id = m.uploader_id AND r.target_type IN (2,3)
  AND r.status IN (0,1,2) AND r.bound_target_id IS NULL
  AND (r.status <> 1 OR r.bound_attachment_id IS NOT NULL)
  AND (a.object_key IS NULL OR BINARY a.object_key = BINARY m.object_key)
  AND m.cos_exists = 1 AND TRIM(m.evidence_ref) <> '';
SET @media_verified_count = (SELECT COUNT(*) FROM media_attachment_verified_mapping);
SET @media_eligible_count = (SELECT COUNT(*) FROM media_attachment_eligible_mapping);
SET @media_repair_valid = @media_verified_count BETWEEN 1 AND 100 AND @media_eligible_count = @media_verified_count;

UPDATE media_attachment a JOIN media_attachment_eligible_mapping m ON a.id = m.attachment_id
SET a.object_key = m.object_key WHERE @media_repair_valid;
UPDATE media_upload_record r JOIN (
    SELECT upload_record_id, MIN(attachment_id) AS attachment_id
    FROM media_attachment_eligible_mapping GROUP BY upload_record_id
) m ON r.id = m.upload_record_id
SET r.status = 1, r.bound_attachment_id = COALESCE(r.bound_attachment_id, m.attachment_id),
    r.last_error = NULL, r.updated_at = NOW()
WHERE @media_repair_valid AND r.bound_target_id IS NULL;

SELECT @media_repair_valid AS batch_eligible, m.attachment_id, a.object_key, r.status,
       r.bound_target_id, r.bound_attachment_id, r.cleanup_started_at
FROM media_attachment_eligible_mapping m JOIN media_attachment a ON a.id = m.attachment_id
JOIN media_upload_record r ON r.id = m.upload_record_id;
ROLLBACK;
DROP TEMPORARY TABLE media_attachment_eligible_mapping;
